// Rigged, animated human avatar for the AI opponent, spectated players and
// remote players. The mesh is a MakeHuman character (public/models/player.glb,
// CC0, generated by tools/build-humans.ts with Mixamo bone names) and the game
// drives it on top of its idle / walk / run clips, each avatar at its own
// slightly shifted tempo: the body shadows the paddle with real footwork,
// bends its knees and waist so the grip is within the arm's real reach, a
// two-bone IK solve wraps the playing hand around the handle, the head tracks
// the ball, and points trigger win / lose reactions. Remote players use their
// tracked head (height included) and free hand instead.
import * as THREE from './three.ts';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import type { GLTF } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { clone as cloneSkinned } from 'three/examples/jsm/utils/SkeletonUtils.js';
import { HALF_L, PADDLE } from '../core/constants.ts';
import { font } from '../hud/fonts.ts';

const MODEL_URL = `${import.meta.env.BASE_URL}models/player.glb`;
/** the direction the model faces in its own space */
const MODEL_FORWARD = new THREE.Vector3(0, 0, -1);
const MODEL_HEIGHT = 1.8;
/** wrist sits this far down the handle from the grip centre */
const WRIST_BACK = 0.05;
/** how much of the straight arm the IK is allowed to use */
const REACH = 0.93;
/** athletic ready stance: knees and waist always a little bent */
const CROUCH_BASE = 0.32;
const PITCH_BASE = 0.18;
const CROUCH_MAX = 1.05;
const PITCH_MAX = 0.95;

const Y = new THREE.Vector3(0, 1, 0);
const _v1 = new THREE.Vector3();
const _v2 = new THREE.Vector3();
const _v3 = new THREE.Vector3();
const _v4 = new THREE.Vector3();
const _v5 = new THREE.Vector3();
const _q1 = new THREE.Quaternion();
const _q2 = new THREE.Quaternion();
const _q3 = new THREE.Quaternion();
const _m1 = new THREE.Matrix4();
const _m2 = new THREE.Matrix4();
// scratch for the bone helpers only, so callers' scratch quaternions survive a call
const _qa = new THREE.Quaternion();
const _qb = new THREE.Quaternion();
const _qc = new THREE.Quaternion();

// ---------------------------------------------------------------- model cache

let modelLoad: Promise<GLTF | null> | null = null;

function loadModel(): Promise<GLTF | null> {
  modelLoad ??= new GLTFLoader()
    .loadAsync(MODEL_URL)
    .then((gltf) => {
      // fingers are posed by the game (curled around the grip), not by the clips
      for (const clip of gltf.animations) clip.tracks = clip.tracks.filter((t) => !/Hand(Thumb|Index|Middle|Ring|Pinky)/.test(t.name));
      return gltf;
    })
    .catch((e: unknown) => {
      console.warn('avatar model failed to load', e);
      return null;
    });
  return modelLoad;
}

function findBone(root: THREE.Object3D, name: string): THREE.Object3D | undefined {
  return root.getObjectByName(`mixamorig${name}`) ?? root.getObjectByName(`mixamorig:${name}`) ?? root.getObjectByName(name);
}

function bone(root: THREE.Object3D, name: string): THREE.Object3D {
  const b = findBone(root, name);
  if (!b) throw new Error(`avatar rig: missing bone ${name}`);
  return b;
}

const wpos = (o: THREE.Object3D): THREE.Vector3 => o.getWorldPosition(new THREE.Vector3());

/** Apply a world-space rotation delta to a bone (delta must not be _qb/_qc). */
function twistBone(b: THREE.Object3D, delta: THREE.Quaternion): void {
  b.getWorldQuaternion(_qb).premultiply(delta);
  b.parent!.getWorldQuaternion(_qc).invert();
  b.quaternion.multiplyQuaternions(_qc, _qb);
  b.updateWorldMatrix(false, true);
}

/**
 * Rotate a bone in world space so that `from` (a world direction it currently
 * spans) points along `to`, keeping its twist. Children's world matrices are
 * refreshed so the next solve step sees the result.
 */
function aimBone(b: THREE.Object3D, from: THREE.Vector3, to: THREE.Vector3, maxAngle = Math.PI): void {
  const angle = from.angleTo(to);
  if (angle < 1e-4) return;
  _qa.setFromUnitVectors(from, to);
  if (angle > maxAngle) _qa.copy(_qb.identity().slerp(_qa, maxAngle / angle));
  twistBone(b, _qa);
}

interface Arm {
  upper: THREE.Object3D;
  fore: THREE.Object3D;
  hand: THREE.Object3D;
  len1: number;
  len2: number;
  /** finger direction and palm-facing normal, in the hand bone's local frame */
  fLocal: THREE.Vector3;
  nLocal: THREE.Vector3;
}

interface Leg {
  up: THREE.Object3D;
  low: THREE.Object3D;
  foot: THREE.Object3D;
}

interface Rig {
  model: THREE.Object3D;
  mixer: THREE.AnimationMixer;
  idle: THREE.AnimationAction;
  walk: THREE.AnimationAction;
  run: THREE.AnimationAction;
  right: Arm;
  left: Arm;
  legs: Leg[];
  hips: THREE.Object3D;
  head: THREE.Object3D;
  spine: THREE.Object3D;
  /** model forward, in the head bone's local frame */
  headFwd: THREE.Vector3;
  /** rest-pose measurements (metres): playing shoulder relative to the feet */
  shoulderRight: number;
  shoulderUp: number;
  shoulderFwd: number;
  /** waist (Spine1) to shoulder, vertical */
  spineLen: number;
  /** thigh + shin */
  legLen: number;
  headUp: number;
  /** the shirt (tinted per personality) */
  mats: THREE.MeshStandardMaterial[];
  /** this avatar's playback rate for the shared clips, so two never move in step */
  tempo: number;
  /**
   * The pose the mixer produced last frame for every bone the game then bends
   * further. The bends are deltas, and the mixer skips bones whose clip value
   * did not change, so without restoring this first the deltas would pile up
   * frame after frame (legs spinning like a fan).
   */
  mixed: { bone: THREE.Object3D; q: THREE.Quaternion; p: THREE.Vector3 }[];
}

function labelTexture(text: string, color: string): THREE.CanvasTexture {
  const c = document.createElement('canvas');
  c.width = 512;
  c.height = 96;
  const g = c.getContext('2d')!;
  g.fillStyle = 'rgba(8,10,18,0.72)';
  g.beginPath();
  g.roundRect(4, 4, 504, 88, 24);
  g.fill();
  g.fillStyle = color;
  g.font = font(700, 48);
  g.textAlign = 'center';
  g.textBaseline = 'middle';
  g.fillText(text, 256, 50, 480);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

export type Reaction = 'win' | 'lose';

export class Avatar {
  group = new THREE.Group();
  /** which end of the table this avatar stands at */
  side: 1 | -1;
  private rig: Rig | null = null;
  private label: THREE.Sprite;
  private bubble: THREE.Sprite;
  private bubbleLife = 0;
  private tint: number;
  private bodyX = 0;
  private bodyZ: number;
  private yaw: number;
  private speed = 0;
  private crouch = CROUCH_BASE;
  private pitch = PITCH_BASE;
  private headPos = new THREE.Vector3();
  private headQuat = new THREE.Quaternion();
  private hasHeadPose = false;
  private freeHand: THREE.Vector3 | null = null;
  private reaction: Reaction | null = null;
  private reactT = 0;
  private time = 0;
  /** label anchor (table space), updated every frame */
  private labelAt = new THREE.Vector3();
  private rootQ = new THREE.Quaternion();
  private fwd = new THREE.Vector3();

  constructor(side: 1 | -1, name: string, shirtColor = 0xd23b3b) {
    this.side = side;
    this.bodyZ = side * (HALF_L + 0.75);
    this.yaw = this.baseYaw();
    this.tint = shirtColor;
    this.labelAt.set(0, 1.62, this.bodyZ);

    this.label = new THREE.Sprite(new THREE.SpriteMaterial({ map: labelTexture(name, '#ffffff'), depthWrite: false, transparent: true }));
    this.label.scale.set(0.5, 0.094, 1);
    this.group.add(this.label);
    this.bubble = new THREE.Sprite(new THREE.SpriteMaterial({ map: labelTexture('', '#ffe066'), depthWrite: false, transparent: true }));
    this.bubble.scale.set(0.62, 0.116, 1);
    this.bubble.visible = false;
    this.group.add(this.bubble);

    void loadModel().then((gltf) => {
      if (gltf) this.attach(gltf);
    });
  }

  /** yaw that makes the model face the other end of the table */
  private baseYaw(): number {
    // model forward -Z: yaw 0 faces -Z (near player looks down the table), PI faces +Z
    return this.side === -1 ? Math.PI : 0;
  }

  private attach(gltf: GLTF): void {
    const model = cloneSkinned(gltf.scene);
    const all: THREE.MeshStandardMaterial[] = [];
    const shirts: THREE.MeshStandardMaterial[] = [];
    model.traverse((o) => {
      const m = o as THREE.Mesh;
      if (!m.isMesh) return;
      m.frustumCulled = false; // skinned bounds don't follow the pose
      const src = (Array.isArray(m.material) ? m.material : [m.material]) as THREE.MeshStandardMaterial[];
      const cloned = src.map((s) => {
        const mat = s.clone();
        all.push(mat);
        if (mat.name === 'shirt') shirts.push(mat);
        return mat;
      });
      m.material = Array.isArray(m.material) ? cloned : cloned[0];
    });
    // tint the shirt only (a model without a named shirt is tinted whole)
    const mats = shirts.length ? shirts : all;
    for (const mat of mats) mat.color.setHex(this.tint);
    model.updateWorldMatrix(true, true);
    const box = new THREE.Box3().setFromObject(model);
    const h = box.max.y - box.min.y;
    if (h > 0.5 && h < 4) model.scale.multiplyScalar(MODEL_HEIGHT / h);
    model.updateWorldMatrix(true, true);

    const arm = (s: 'Right' | 'Left'): Arm => {
      const upper = bone(model, `${s}Arm`);
      const fore = bone(model, `${s}ForeArm`);
      const hand = bone(model, `${s}Hand`);
      const pU = wpos(upper),
        pF = wpos(fore),
        pH = wpos(hand);
      const f = wpos(bone(model, `${s}HandMiddle1`)).sub(pH).normalize();
      const t = wpos(bone(model, `${s}HandThumb1`)).sub(pH).normalize();
      // palm-facing normal: fingers x thumb for a right hand, the reverse for a left
      const n = s === 'Right' ? new THREE.Vector3().crossVectors(f, t) : new THREE.Vector3().crossVectors(t, f);
      n.addScaledVector(f, -n.dot(f)).normalize();
      const inv = hand.getWorldQuaternion(new THREE.Quaternion()).invert();
      const a: Arm = { upper, fore, hand, len1: pU.distanceTo(pF), len2: pF.distanceTo(pH), fLocal: f.clone().applyQuaternion(inv), nLocal: n.clone().applyQuaternion(inv) };
      // curl the fingers: a grip on the playing hand, relaxed on the other
      const playing = s === 'Right'; // avatars are right-handed
      const axis = new THREE.Vector3().crossVectors(f, n).normalize();
      for (const finger of ['Index', 'Middle', 'Ring', 'Pinky']) {
        for (let i = 1; i <= 3; i++) {
          const ph = findBone(model, `${s}Hand${finger}${i}`);
          if (!ph) continue;
          const curl = (playing ? [0.55, 0.85, 0.6] : [0.3, 0.45, 0.3])[i - 1];
          twistBone(ph, _q1.setFromAxisAngle(axis, curl));
        }
      }
      for (let i = 1; i <= 3; i++) {
        const ph = findBone(model, `${s}HandThumb${i}`);
        if (ph) twistBone(ph, _q1.setFromAxisAngle(axis, 0.2));
      }
      return a;
    };
    const right = arm('Right');
    const left = arm('Left');
    const legs: Leg[] = (['Right', 'Left'] as const).map((s) => ({ up: bone(model, `${s}UpLeg`), low: bone(model, `${s}Leg`), foot: bone(model, `${s}Foot`) }));

    const head = bone(model, 'Head');
    const headFwd = MODEL_FORWARD.clone().applyQuaternion(head.getWorldQuaternion(new THREE.Quaternion()).invert()).normalize();
    const spine = bone(model, 'Spine1');
    const pS = wpos(right.upper);
    const legLen = wpos(legs[0].up).distanceTo(wpos(legs[0].low)) + wpos(legs[0].low).distanceTo(wpos(legs[0].foot));

    const mixer = new THREE.AnimationMixer(model);
    const clip = (n: string): THREE.AnimationClip => gltf.animations.find((c) => c.name.toLowerCase() === n) ?? gltf.animations[0];
    const idle = mixer.clipAction(clip('idle'));
    const walk = mixer.clipAction(clip('walk'));
    const run = mixer.clipAction(clip('run'));
    // the same clips for every avatar, but each at its own shifted tempo and phase
    const tempo = 0.9 + Math.random() * 0.2;
    for (const a of [idle, walk, run]) {
      a.enabled = true;
      a.setEffectiveTimeScale(tempo);
      a.setEffectiveWeight(a === idle ? 1 : 0);
      a.play();
    }
    idle.time = Math.random() * 2;

    this.rig = {
      model,
      mixer,
      idle,
      walk,
      run,
      right,
      left,
      legs,
      hips: bone(model, 'Hips'),
      head,
      spine,
      headFwd,
      // model faces -Z and its right is +X
      shoulderRight: pS.x,
      shoulderUp: pS.y,
      shoulderFwd: -pS.z,
      spineLen: Math.max(0.2, pS.y - wpos(spine).y),
      legLen,
      headUp: wpos(head).y,
      mats,
      tempo,
      mixed: [bone(model, 'Hips'), spine, head, ...legs.flatMap((l) => [l.up, l.low, l.foot]), ...[right, left].flatMap((a) => [a.upper, a.fore, a.hand])].map((b) => ({ bone: b, q: b.quaternion.clone(), p: b.position.clone() })),
    };
    model.position.set(this.bodyX, 0, this.bodyZ);
    model.rotation.y = this.yaw;
    this.group.add(model);
  }

  setName(name: string): void {
    const m = this.label.material as THREE.SpriteMaterial;
    m.map?.dispose();
    m.map = labelTexture(name, '#ffffff');
    m.needsUpdate = true;
  }

  setShirt(color: number): void {
    this.tint = color;
    if (this.rig) for (const m of this.rig.mats) m.color.setHex(color);
  }

  say(text: string): void {
    const m = this.bubble.material as THREE.SpriteMaterial;
    m.map?.dispose();
    m.map = labelTexture(text, '#ffe066');
    m.needsUpdate = true;
    this.bubble.visible = true;
    this.bubbleLife = 3;
  }

  /** Celebrate or sulk for a couple of seconds (after a point). */
  react(kind: Reaction, seconds = 1.8): void {
    this.reaction = kind;
    this.reactT = seconds;
  }

  /** Remote player: use their real head pose and (optionally) free hand. */
  setTracked(head: THREE.Vector3, headQuat: THREE.Quaternion, freeHand: THREE.Vector3 | null): void {
    this.hasHeadPose = true;
    this.headPos.copy(head);
    this.headQuat.copy(headQuat);
    this.freeHand = freeHand;
  }

  /**
   * @param paddlePos  blade centre in table space
   * @param paddleQuat paddle orientation
   * @param lookAt     what the eyes follow (the ball), table space
   */
  update(dt: number, paddlePos: THREE.Vector3, paddleQuat: THREE.Quaternion, lookAt?: THREE.Vector3): void {
    this.time += dt;
    const s = this.side;
    const up = _v1.set(0, 1, 0).applyQuaternion(paddleQuat);
    // grip centre = blade centre pulled back along the handle; the wrist sits a little further back
    const grip = _v2.set(0, -PADDLE.gripToBlade, 0).applyQuaternion(paddleQuat).add(paddlePos);
    const wrist = _v3.copy(grip).addScaledVector(up, -WRIST_BACK);
    if (this.reactT > 0) {
      this.reactT -= dt;
      if (this.reactT <= 0) this.reaction = null;
    }
    const rig = this.rig;
    const fwd = this.fwd.set(0, 0, -s); // the way this player faces, table space
    const k = Math.min(1, dt * 5);

    // ---- stance: where the body stands and how far it bends to reach the grip
    const prevX = this.bodyX,
      prevZ = this.bodyZ;
    let headY = 1.62;
    let yawTarget = this.baseYaw();
    let crouch = CROUCH_BASE,
      pitch = PITCH_BASE;
    if (this.hasHeadPose) {
      headY = this.headPos.y;
      if (rig) {
        // crouch so the model's head is as low as the tracked headset
        const drop = Math.max(0, rig.headUp - this.headPos.y);
        crouch = Math.acos(THREE.MathUtils.clamp(1 - drop / rig.legLen, Math.cos(CROUCH_MAX), 1));
        pitch = 0.1;
        this.bodyX = this.headPos.x;
        this.bodyZ = this.headPos.z + s * 0.06;
      } else {
        this.bodyX = this.headPos.x;
        this.bodyZ = this.headPos.z + s * 0.06;
      }
      const f = _v4.set(0, 0, -1).applyQuaternion(this.headQuat);
      if (f.x * f.x + f.z * f.z > 0.05) yawTarget = Math.atan2(-f.x, -f.z);
    } else if (rig) {
      // solve a stance that puts the wrist inside the arm's reach: lower the
      // shoulder by bending the waist, then the knees, then stand close enough
      const R = (rig.right.len1 + rig.right.len2) * REACH;
      const shoulderY = (c: number, p: number): number => rig.shoulderUp - rig.legLen * (1 - Math.cos(c)) - rig.spineLen * (1 - Math.cos(p));
      let dy = shoulderY(crouch, pitch) - wrist.y;
      const dyMax = R * 0.92; // the arm may hang almost straight down to the grip
      if (dy > dyMax) {
        // share the drop between knees and waist, spilling over when one saturates
        const need = dy - dyMax;
        const bend = (angle: number, len: number, max: number, drop: number): number => Math.acos(THREE.MathUtils.clamp(Math.cos(angle) - drop / len, Math.cos(max), 1));
        const c2 = bend(crouch, rig.legLen, CROUCH_MAX, need * 0.5);
        const gotC = rig.legLen * (Math.cos(crouch) - Math.cos(c2));
        const p2 = bend(pitch, rig.spineLen, PITCH_MAX, need - gotC);
        const gotP = rig.spineLen * (Math.cos(pitch) - Math.cos(p2));
        crouch = need - gotP > gotC ? bend(crouch, rig.legLen, CROUCH_MAX, need - gotP) : c2;
        pitch = p2;
        dy = shoulderY(crouch, pitch) - wrist.y;
      }
      dy = THREE.MathUtils.clamp(dy, -dyMax, dyMax);
      const hz = Math.sqrt(Math.max(0, R * R - dy * dy)) * 0.9;
      const shoulderFwd = rig.shoulderFwd + rig.spineLen * Math.sin(pitch);
      // the shoulder stands above the wrist (sideways) and `hz` behind it (depth)
      const wantX = wrist.x - s * rig.shoulderRight;
      const wantZ = Math.max(HALF_L + 0.22, Math.abs(wrist.z) + hz + shoulderFwd) * s;
      this.bodyX += (wantX - this.bodyX) * k;
      this.bodyZ += (wantZ - this.bodyZ) * k;
    } else {
      this.bodyX += (grip.x - s * 0.24 - this.bodyX) * k;
      this.bodyZ += (Math.max(HALF_L + 0.4, Math.abs(grip.z) + 0.4) * s - this.bodyZ) * k;
    }
    if (this.reaction === 'lose') pitch += 0.2;
    this.crouch += (crouch - this.crouch) * Math.min(1, dt * 6);
    this.pitch += (pitch - this.pitch) * Math.min(1, dt * 6);

    // speed drives walk/run and a turn into the movement direction
    if (dt > 0) {
      const vx = (this.bodyX - prevX) / dt,
        vz = (this.bodyZ - prevZ) / dt;
      const sp = Math.hypot(vx, vz);
      this.speed += (sp - this.speed) * Math.min(1, dt * 8);
      if (!this.hasHeadPose && sp > 0.25) {
        let d = Math.atan2(-vx, -vz) - this.baseYaw();
        d = Math.atan2(Math.sin(d), Math.cos(d));
        yawTarget = this.baseYaw() + THREE.MathUtils.clamp(d, -0.7, 0.7) * Math.min(1, sp / 1.2);
      }
    }
    let dy = yawTarget - this.yaw;
    dy = Math.atan2(Math.sin(dy), Math.cos(dy));
    this.yaw += dy * Math.min(1, dt * 6);

    if (!rig) {
      this.labelAt.set(this.bodyX, headY, this.bodyZ);
      this.updateSprites(dt, headY);
      return;
    }

    // ---- animation: idle <-> walk <-> run by speed
    const walkW = THREE.MathUtils.clamp((this.speed - 0.12) / 0.4, 0, 1);
    const runW = THREE.MathUtils.clamp((this.speed - 1.3) / 0.8, 0, 1);
    rig.run.setEffectiveWeight(runW);
    rig.walk.setEffectiveWeight(walkW * (1 - runW));
    rig.idle.setEffectiveWeight(1 - Math.max(walkW, runW));
    rig.walk.setEffectiveTimeScale(THREE.MathUtils.clamp(this.speed / 1.1, 0.7, 1.8) * rig.tempo);
    rig.run.setEffectiveTimeScale(THREE.MathUtils.clamp(this.speed / 2.6, 0.8, 1.5) * rig.tempo);
    rig.model.position.set(this.bodyX, 0, this.bodyZ);
    rig.model.rotation.y = this.yaw;
    // start from the clip pose, not from last frame's bent one
    for (const m of rig.mixed) {
      m.bone.quaternion.copy(m.q);
      m.bone.position.copy(m.p);
    }
    rig.mixer.update(dt);
    for (const m of rig.mixed) {
      m.q.copy(m.bone.quaternion);
      m.p.copy(m.bone.position);
    }
    this.group.updateWorldMatrix(true, true);
    const rootQ = this.group.getWorldQuaternion(this.rootQ); // table -> world rotation

    // ---- knees: thighs forward, shins back, feet flat; hips drop to match
    const c = this.crouch;
    if (c > 0.01) {
      const drop = rig.legLen * (1 - Math.cos(c));
      const hw = wpos(rig.hips);
      hw.y -= drop;
      rig.hips.position.copy(rig.hips.parent!.worldToLocal(hw));
      rig.hips.updateWorldMatrix(false, true);
      const kneeAxis = _v4.crossVectors(_v5.set(0, -1, 0), fwd).normalize().applyQuaternion(rootQ);
      for (const leg of rig.legs) {
        twistBone(leg.up, _q1.setFromAxisAngle(kneeAxis, c));
        twistBone(leg.low, _q1.setFromAxisAngle(kneeAxis, -2 * c));
        twistBone(leg.foot, _q1.setFromAxisAngle(kneeAxis, c));
      }
    }

    // ---- torso: bend forward to reach, lean toward the grip
    const lateral = THREE.MathUtils.clamp((grip.x - this.bodyX) * 0.5, -0.35, 0.35);
    _q2.setFromAxisAngle(_v5.set(0, 0, 1).applyQuaternion(rootQ), -lateral);
    _q3.setFromAxisAngle(_v5.crossVectors(Y, fwd).applyQuaternion(rootQ), this.pitch);
    twistBone(rig.spine, _q2.premultiply(_q3));

    // ---- playing arm (right): IK to the wrist, hand wrapped around the handle
    const wristW = _v5.copy(wrist).applyMatrix4(this.group.matrixWorld);
    // elbow out to the player's right (+s X) and back
    const hintR = new THREE.Vector3(s * 0.7, -1, s * 0.35).applyQuaternion(rootQ);
    const fW = up.clone().applyQuaternion(rootQ);
    const nW = new THREE.Vector3(1, 0, 0).applyQuaternion(paddleQuat).applyQuaternion(rootQ);
    this.solveArm(rig.right, wristW, hintR, fW, nW);

    // ---- free arm (left): tracked hand, a fist pump, or the clip's own motion
    let freeTarget: THREE.Vector3 | null = null;
    if (this.freeHand) freeTarget = this.freeHand.clone();
    else if (this.reaction === 'win') {
      const sh = wpos(rig.left.upper).applyMatrix4(_m1.copy(this.group.matrixWorld).invert());
      const pump = 0.4 + Math.sin(this.time * 14) * 0.06;
      freeTarget = sh.add(new THREE.Vector3(-s * 0.15, pump, -s * 0.12));
    }
    if (freeTarget) {
      const hintL = new THREE.Vector3(-s * 0.7, -1, s * 0.3).applyQuaternion(rootQ);
      this.solveArm(rig.left, freeTarget.applyMatrix4(this.group.matrixWorld), hintL);
    }

    // ---- head: follow the ball (or the tracked headset)
    const headW = wpos(rig.head);
    let want: THREE.Vector3;
    if (this.hasHeadPose) want = new THREE.Vector3(0, 0, -1).applyQuaternion(this.headQuat).applyQuaternion(rootQ);
    else if (this.reaction === 'lose') want = new THREE.Vector3(this.bodyX, 0, this.bodyZ - s * 0.9).applyMatrix4(this.group.matrixWorld).sub(headW).normalize();
    else if (this.reaction === 'win') want = new THREE.Vector3(fwd.x, 0.9, fwd.z).normalize().applyQuaternion(rootQ);
    else if (lookAt) want = lookAt.clone().applyMatrix4(this.group.matrixWorld).sub(headW).normalize();
    else want = grip.clone().applyMatrix4(this.group.matrixWorld).sub(headW).normalize();
    const cur = rig.headFwd.clone().applyQuaternion(rig.head.getWorldQuaternion(_q2)).normalize();
    // never twist the neck past what a person can do
    const bodyFwd = fwd.clone().applyQuaternion(rootQ);
    if (bodyFwd.angleTo(want) > 1.2) want.copy(bodyFwd).lerp(want, 0.5).normalize();
    aimBone(rig.head, cur, want, 0.9);

    // ---- sprites
    this.labelAt.copy(headW).applyMatrix4(_m1.copy(this.group.matrixWorld).invert());
    this.updateSprites(dt, this.labelAt.y);
  }

  private updateSprites(dt: number, headY: number): void {
    this.label.position.set(this.labelAt.x, headY + 0.3, this.labelAt.z);
    if (this.bubbleLife > 0) {
      this.bubbleLife -= dt;
      this.bubble.position.set(this.labelAt.x, headY + 0.44, this.labelAt.z);
      (this.bubble.material as THREE.SpriteMaterial).opacity = Math.min(1, this.bubbleLife);
      if (this.bubbleLife <= 0) this.bubble.visible = false;
    }
  }

  /**
   * Two-bone IK in world space: upper arm to the elbow, forearm to the wrist
   * target, then (optionally) the hand's finger direction `f` and palm normal
   * `n` are matched so the hand wraps the handle.
   */
  private solveArm(arm: Arm, target: THREE.Vector3, bendHint: THREE.Vector3, f?: THREE.Vector3, n?: THREE.Vector3): void {
    const shoulder = wpos(arm.upper);
    const dir = new THREE.Vector3().subVectors(target, shoulder);
    const L1 = arm.len1,
      L2 = arm.len2;
    let d = dir.length();
    d = THREE.MathUtils.clamp(d, Math.abs(L1 - L2) + 0.01, L1 + L2 - 0.01);
    dir.normalize();
    const a = (L1 * L1 - L2 * L2 + d * d) / (2 * d);
    const h = Math.sqrt(Math.max(0, L1 * L1 - a * a));
    const perp = bendHint.clone().addScaledVector(dir, -bendHint.dot(dir));
    if (perp.lengthSq() < 1e-6) perp.set(0, -1, 0).addScaledVector(dir, dir.y);
    perp.normalize();
    const elbow = shoulder.clone().addScaledVector(dir, a).addScaledVector(perp, h);

    const forePos = wpos(arm.fore);
    aimBone(arm.upper, forePos.sub(shoulder).normalize(), elbow.clone().sub(shoulder).normalize());
    arm.fore.getWorldPosition(forePos);
    const handPos = wpos(arm.hand);
    aimBone(arm.fore, handPos.sub(forePos).normalize(), target.clone().sub(forePos).normalize());

    if (f && n) {
      // hand world rotation R with R * fLocal = f and R * nLocal = n
      const nn = n.clone().addScaledVector(f, -n.dot(f)).normalize();
      _m1.makeBasis(arm.fLocal, arm.nLocal, _v4.crossVectors(arm.fLocal, arm.nLocal)).transpose();
      _m2.makeBasis(f, nn, _v4.crossVectors(f, nn)).multiply(_m1);
      _q2.setFromRotationMatrix(_m2);
      arm.hand.parent!.getWorldQuaternion(_q3).invert();
      arm.hand.quaternion.multiplyQuaternions(_q3, _q2);
      arm.hand.updateWorldMatrix(false, true);
    }
  }
}
